package com.example.starter.batch;

import com.example.starter.batch.dto.ConfigureDividersResponse;
import com.example.starter.batch.dto.LoadPalletRequest;
import com.example.starter.batch.dto.LoadPalletResponse;
import com.example.starter.batch.dto.LoadingDetail;
import com.example.starter.batch.dto.PalletDetailResponse;
import com.example.starter.batch.dto.PalletEventResponse;
import com.example.starter.batch.dto.PalletResponse;
import com.example.starter.batch.dto.QuarantinePalletResponse;
import com.example.starter.batch.dto.ReviewFlagResponse;
import com.example.starter.batch.dto.ShipPalletResponse;
import com.example.starter.batch.dto.UnloadPalletRequest;
import com.example.starter.batch.dto.UnloadPalletResponse;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Clock;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.function.Supplier;
import java.util.stream.Collectors;

/**
 * 批次托盘隔离核心服务。
 *
 * <p>并发裁决：装载事务先按 batchKey 升序锁定各批次行、再锁定托盘行（全局统一“先批次后托盘”
 * 的锁顺序，与召回事务一致，避免死锁）；同一批次的并发装载在批次行锁上串行，
 * 并由 {@code uk_loading_active_batch} 唯一索引兜底，保证同一批次并发下只在一个托盘装载成功。
 * 同托盘操作在托盘行锁上串行，按事务提交顺序生效。
 *
 * <p>幂等：commandKey 同参重放首次响应快照，异参 409；失败命令不写 command_log，不占键。
 *
 * <p>整批原则：装载/解除先核对完整最终状态（现有 ACTIVE 装载 + 本次请求的合并布局），
 * 任一校验失败整体回滚，不写任何托盘关系。
 */
@Service
public class PalletService {

    static final String CMD_CREATE_PALLET = "CREATE_PALLET";
    static final String CMD_CONFIGURE_DIVIDERS = "CONFIGURE_DIVIDERS";
    static final String CMD_LOAD = "LOAD_PALLET";
    static final String CMD_UNLOAD = "UNLOAD_PALLET";
    static final String CMD_SHIP = "SHIP_PALLET";
    static final String CMD_QUARANTINE = "QUARANTINE_PALLET";
    static final String CMD_DECLARE_CATEGORY = "DECLARE_CATEGORY";

    private static final String SEP = "";
    private static final int IDEMPOTENCY_MAX_ATTEMPTS = 3;

    /**
     * 允许装载托盘的批次状态：仅未放行、未拒绝、未召回、未拆分的在制批次（待运批次）。
     */
    private static final Set<BatchStatus> LOADABLE_STATUSES = Set.of(
            BatchStatus.QUARANTINED, BatchStatus.PENDING_RELEASE, BatchStatus.RELEASE_REVIEW);

    private final PalletRepository palletRepo;
    private final BatchRepository batchRepo;
    private final TransactionTemplate tx;
    private final ObjectMapper objectMapper;
    private final Clock clock;

    public PalletService(PalletRepository palletRepo,
                         BatchRepository batchRepo,
                         PlatformTransactionManager transactionManager,
                         ObjectMapper objectMapper,
                         Clock clock) {
        this.palletRepo = palletRepo;
        this.batchRepo = batchRepo;
        this.tx = new TransactionTemplate(transactionManager);
        this.objectMapper = objectMapper;
        this.clock = clock;
    }

    // ========== 隔离类别声明 ==========

    /**
     * 声明批次隔离类别；类别一经声明不可更改：同类别换 commandKey 重复声明返回当前声明（200），
     * 换类别返回 409。
     */
    public StoredResponse declareCategory(String batchKey, String category, String commandKey) {
        String fingerprint = fingerprint("declare", batchKey, category);
        return executeIdempotent(CMD_DECLARE_CATEGORY, commandKey, fingerprint, () -> {
            BatchRepository.BatchRow batch = batchRepo.findBatchForUpdate(batchKey)
                    .orElseThrow(() -> ApiException.notFound("批次不存在: " + batchKey));
            if (batch.segregationCategory() != null) {
                if (!batch.segregationCategory().equals(category)) {
                    throw ApiException.conflict("隔离类别已声明为 " + batch.segregationCategory()
                            + "，不可更改为 " + category);
                }
                var existing = batchRepo.findCategory(batchKey).orElseThrow();
                return new StoredResponse(200, toJson(new com.example.starter.batch.dto
                        .SegregationCategoryResponse(batchKey, category,
                        Instant.parse(existing.declaredAt()))));
            }
            String now = now();
            int updated = batchRepo.declareCategory(batchKey, category, now);
            if (updated == 0) {
                throw ApiException.conflict("隔离类别并发声明冲突: " + batchKey);
            }
            return new StoredResponse(201, toJson(new com.example.starter.batch.dto
                    .SegregationCategoryResponse(batchKey, category, Instant.parse(now))));
        });
    }

    // ========== 托盘生命周期 ==========

    /**
     * 创建托盘：初始 OPEN、隔板数量可指定（默认 0）、隔板版本 0；palletKey 重复返回 409。
     */
    public StoredResponse createPallet(String palletKey, Integer dividerCount, String commandKey) {
        int dividers = dividerCount == null ? 0 : dividerCount;
        String fingerprint = fingerprint("createPallet", palletKey, String.valueOf(dividers));
        return executeIdempotent(CMD_CREATE_PALLET, commandKey, fingerprint, () -> {
            palletRepo.findPallet(palletKey).ifPresent(p -> {
                throw ApiException.conflict("palletKey 已存在: " + palletKey);
            });
            String now = now();
            palletRepo.insertPallet(new PalletRepository.PalletRow(0L, palletKey, dividers, 0,
                    PalletStatus.OPEN.name(), now));
            return new StoredResponse(201, toJson(toPalletResponse(
                    new PalletRepository.PalletRow(0L, palletKey, dividers, 0,
                            PalletStatus.OPEN.name(), now), List.of())));
        });
    }

    /**
     * 配置隔板数量：仅 OPEN 托盘可改；数量实际变化才递增隔板版本并记录事件，相同数量为无效变更空操作。
     */
    public StoredResponse configureDividers(String palletKey, int dividerCount, String commandKey) {
        String fingerprint = fingerprint("dividers", palletKey, String.valueOf(dividerCount));
        return executeIdempotent(CMD_CONFIGURE_DIVIDERS, commandKey, fingerprint, () -> {
            PalletRepository.PalletRow pallet = lockOpenPallet(palletKey);
            int previous = pallet.dividerCount();
            if (previous == dividerCount) {
                return new StoredResponse(200, toJson(new ConfigureDividersResponse(
                        palletKey, previous, previous, pallet.dividerVersion(), 0, false,
                        Instant.parse(now()))));
            }
            int newVersion = pallet.dividerVersion() + 1;
            String now = now();
            palletRepo.updateDividers(palletKey, dividerCount, newVersion);
            palletRepo.insertEvent(new PalletRepository.EventRow(0L, palletKey,
                    PalletEventType.DIVIDERS_CONFIGURED.name(),
                    "隔板数量变更：实际 " + dividerCount + "，原实际值 " + previous
                            + "，差额 " + (dividerCount - previous) + "，新版本 " + newVersion, now));
            return new StoredResponse(200, toJson(new ConfigureDividersResponse(
                    palletKey, dividerCount, previous, newVersion, dividerCount - previous, true,
                    Instant.parse(now))));
        });
    }

    /**
     * 整批装载：一次校验请求内重复、批次存在/已声明类别/未召回/未放行/未被占用，
     * 以及与托盘现有 ACTIVE 装载合并后的完整最终隔离关系；任一失败 422/409 整体回滚。
     */
    public StoredResponse load(String palletKey, LoadPalletRequest req) {
        List<LoadPalletRequest.Entry> entries = req.entries();
        List<SegregationRules.Placed> requestPlaced = entries.stream()
                .map(e -> new SegregationRules.Placed(e.batchKey(), null, e.slotNo()))
                .toList();
        String duplicated = SegregationRules.findRequestDuplication(requestPlaced);
        if (duplicated != null) {
            String code = duplicated.startsWith("分隔位") ? "SLOT_DUPLICATE" : "REQUEST_BATCH_DUPLICATE";
            throw ApiException.unprocessable(code, duplicated);
        }

        List<String> fingerprintParts = new ArrayList<>();
        fingerprintParts.add("load");
        fingerprintParts.add(palletKey);
        for (LoadPalletRequest.Entry e : entries) {
            fingerprintParts.add(e.batchKey());
            fingerprintParts.add(String.valueOf(e.slotNo()));
        }
        String fingerprint = fingerprint(fingerprintParts.toArray(new String[0]));

        return executeIdempotent(CMD_LOAD, req.commandKey(), fingerprint, () -> {
            // 无锁预读托盘：不存在 404；已冻结/已隔离 409
            PalletRepository.PalletRow preview = palletRepo.findPallet(palletKey)
                    .orElseThrow(() -> ApiException.notFound("托盘不存在: " + palletKey));
            if (!PalletStatus.OPEN.name().equals(preview.status())) {
                throw ApiException.conflict("托盘状态 " + preview.status()
                        + " 不允许装载，仅 OPEN 托盘可装载");
            }

            // 1) 先按 batchKey 升序锁定全部批次行（全局锁顺序：先批次后托盘）
            List<String> batchKeys = entries.stream().map(LoadPalletRequest.Entry::batchKey)
                    .sorted().toList();
            Map<String, BatchRepository.BatchRow> batches = new LinkedHashMap<>();
            for (String key : batchKeys) {
                BatchRepository.BatchRow row = batchRepo.findBatchForUpdate(key)
                        .orElseThrow(() -> ApiException.notFound("批次不存在: " + key));
                batches.put(key, row);
            }
            // 锁后重查命令快照：并发同键可能已由对方提交
            var logged = palletRepo.findCommand(CMD_LOAD, req.commandKey());
            if (logged.isPresent()) {
                return replayOrConflict(logged.get(), fingerprint);
            }

            // 2) 逐批状态与占用校验（原因可区分）
            for (LoadPalletRequest.Entry e : entries) {
                BatchRepository.BatchRow batch = batches.get(e.batchKey());
                if (batch.segregationCategory() == null) {
                    throw ApiException.unprocessable("CATEGORY_NOT_DECLARED",
                            "批次未声明隔离类别，不能装载: " + e.batchKey());
                }
                BatchStatus status = BatchStatus.valueOf(batch.status());
                if (status == BatchStatus.RECALLED) {
                    throw ApiException.unprocessable("BATCH_RECALLED",
                            "批次已召回，不能装载: " + e.batchKey());
                }
                if (status == BatchStatus.REJECTED) {
                    throw ApiException.unprocessable("BATCH_REJECTED",
                            "批次已拒收，不能装载: " + e.batchKey());
                }
                if (status == BatchStatus.RELEASED || status == BatchStatus.SPLIT) {
                    throw ApiException.unprocessable("BATCH_ALREADY_RELEASED",
                            "批次已放行（" + status + "），不能装载待运托盘: " + e.batchKey());
                }
                if (!LOADABLE_STATUSES.contains(status)) {
                    throw ApiException.unprocessable("BATCH_STATUS_INVALID",
                            "批次状态 " + status + " 不允许装载: " + e.batchKey());
                }
                if (recalledAncestor(e.batchKey()).isPresent()) {
                    throw ApiException.unprocessable("ANCESTOR_RECALLED",
                            "批次的祖先批次已召回，不能装载: " + e.batchKey());
                }
                palletRepo.findActiveLoadingByBatch(e.batchKey()).ifPresent(loading -> {
                    if (loading.palletKey().equals(palletKey)) {
                        throw ApiException.conflict("批次已在本托盘当前装载中: " + e.batchKey());
                    }
                    throw ApiException.unprocessable("BATCH_OCCUPIED_OTHER_PALLET",
                            "批次已被其他托盘 " + loading.palletKey() + " 占用: " + e.batchKey());
                });
            }

            // 3) 再锁定托盘并重读状态与当前装载
            PalletRepository.PalletRow pallet = lockPalletForUpdate(palletKey);
            if (!PalletStatus.OPEN.name().equals(pallet.status())) {
                throw ApiException.conflict("托盘状态 " + pallet.status()
                        + " 不允许装载，仅 OPEN 托盘可装载");
            }
            List<PalletRepository.LoadingRow> current = palletRepo.findActiveLoadings(palletKey);

            // 4) 合并出完整最终隔离关系并校验
            List<SegregationRules.Placed> finalPlacement = new ArrayList<>();
            for (PalletRepository.LoadingRow row : current) {
                finalPlacement.add(new SegregationRules.Placed(
                        row.batchKey(), row.segregationCategory(), row.slotNo()));
            }
            for (LoadPalletRequest.Entry e : entries) {
                finalPlacement.add(new SegregationRules.Placed(
                        e.batchKey(), batches.get(e.batchKey()).segregationCategory(), e.slotNo()));
            }
            if (!SegregationRules.slotsDistinct(finalPlacement)) {
                throw ApiException.unprocessable("SLOT_DUPLICATE",
                        "分隔位冲突：分隔位 " + collidingSlot(finalPlacement)
                                + " 已被托盘内其他批次占用，不同批次必须分配到不同分隔位");
            }
            int required = SegregationRules.requiredDividerCount(finalPlacement);
            if (pallet.dividerCount() < required) {
                String code = pallet.dividerCount() == 0 ? "CATEGORY_CONFLICT" : "DIVIDER_SHORTAGE";
                long categories = SegregationRules.distinctCategoryCount(finalPlacement);
                throw ApiException.unprocessable(code,
                        "类别不同的批次共存需要有效隔板：实际 " + pallet.dividerCount()
                                + "，要求 " + required + "（最终布局含 " + categories
                                + " 个隔离类别），差额 " + (pallet.dividerCount() - required));
            }

            // 5) 一次提交全部装载关系与事件
            String now = now();
            List<LoadingDetail> details = new ArrayList<>(entries.size());
            List<String> eventParts = new ArrayList<>();
            for (int i = 0; i < entries.size(); i++) {
                LoadPalletRequest.Entry e = entries.get(i);
                String category = batches.get(e.batchKey()).segregationCategory();
                palletRepo.insertLoading(new PalletRepository.LoadingRow(0L, palletKey,
                        e.batchKey(), category, e.slotNo(), pallet.dividerVersion(), i + 1, 1,
                        now, null));
                details.add(new LoadingDetail(palletKey, e.batchKey(), category, e.slotNo(),
                        pallet.dividerVersion(), i + 1, Instant.parse(now), null));
                eventParts.add("{batch=" + e.batchKey() + ",category=" + category
                        + ",slot=" + e.slotNo() + "}");
            }
            palletRepo.insertEvent(new PalletRepository.EventRow(0L, palletKey,
                    PalletEventType.LOADED.name(),
                    "装载 " + entries.size() + " 批：" + String.join(",", eventParts)
                            + "；实际隔板 " + pallet.dividerCount() + "，要求 " + required
                            + "，差额 " + (pallet.dividerCount() - required)
                            + "，隔板版本 " + pallet.dividerVersion(), now));

            LoadPalletResponse body = new LoadPalletResponse(palletKey, PalletStatus.OPEN,
                    pallet.dividerCount(), pallet.dividerVersion(), required,
                    pallet.dividerCount() - required, List.copyOf(details), Instant.parse(now));
            return new StoredResponse(201, toJson(body));
        });
    }

    /**
     * 解除装载：仅 OPEN 托盘；请求批次必须全部为该托盘当前 ACTIVE 装载，任一不满足整批失败；
     * 解除释放分隔位（active 置 NULL）与待复核标记，装载历史行与事件保留。
     */
    public StoredResponse unload(String palletKey, UnloadPalletRequest req) {
        List<String> requested = req.batchKeys();
        if (requested.stream().distinct().count() != requested.size()) {
            throw ApiException.badRequest("batchKeys 在解除请求内重复");
        }
        String fingerprint = fingerprint("unload", palletKey,
                String.join(",", requested));
        return executeIdempotent(CMD_UNLOAD, req.commandKey(), fingerprint, () -> {
            PalletRepository.PalletRow pallet = lockOpenPallet(palletKey);
            List<PalletRepository.LoadingRow> active = palletRepo.findActiveLoadings(palletKey);
            Map<String, PalletRepository.LoadingRow> byBatch = active.stream()
                    .collect(Collectors.toMap(PalletRepository.LoadingRow::batchKey, r -> r,
                            (a, b) -> a, LinkedHashMap::new));
            for (String key : requested) {
                if (!byBatch.containsKey(key)) {
                    throw ApiException.unprocessable("BATCH_NOT_ON_PALLET",
                            "批次不在托盘当前装载中，不能解除: " + key);
                }
            }
            String now = now();
            for (String key : requested) {
                PalletRepository.LoadingRow row = byBatch.get(key);
                if (palletRepo.deactivateLoading(row.id(), now) != 1) {
                    throw ApiException.conflict("批次装载并发变更，解除失败: " + key);
                }
                // 随解除释放待复核活标记；REVIEW_FLAGGED 事件作为历史证据保留
                clearReviewFlag(row.batchKey());
            }
            palletRepo.insertEvent(new PalletRepository.EventRow(0L, palletKey,
                    PalletEventType.UNLOADED.name(),
                    "解除 " + requested.size() + " 批（实际释放分隔位 " + requested.size()
                            + "，要求 " + requested.size() + "，差额 0）："
                            + String.join(",", requested) + "；剩余 ACTIVE 装载 "
                            + (active.size() - requested.size()), now));

            UnloadPalletResponse body = new UnloadPalletResponse(palletKey, PalletStatus.OPEN,
                    List.copyOf(requested), requested.size(), requested.size(),
                    active.size() - requested.size(), Instant.parse(now));
            return new StoredResponse(200, toJson(body));
        });
    }

    /**
     * 装运放行：OPEN 托盘且存在装载、无待复核标记且当前隔板仍满足最终隔离关系；
     * 固化托盘、批次、类别、分隔位与隔板版本快照，托盘置 SHIPPED；之后改隔板不追溯。
     */
    public StoredResponse ship(String palletKey, String commandKey) {
        String fingerprint = fingerprint("ship", palletKey);
        return executeIdempotent(CMD_SHIP, commandKey, fingerprint, () -> {
            PalletRepository.PalletRow pallet = lockOpenPallet(palletKey);
            List<PalletRepository.LoadingRow> active = palletRepo.findActiveLoadings(palletKey);
            if (active.isEmpty()) {
                throw ApiException.unprocessable("PALLET_EMPTY", "托盘无当前装载，不能装运放行");
            }
            if (palletRepo.existsReviewFlagForPallet(palletKey)) {
                throw ApiException.unprocessable("PENDING_REVIEW",
                        "托盘存在血缘召回联动的待复核批次，复核解除前不能装运放行");
            }
            List<SegregationRules.Placed> placement = active.stream()
                    .map(r -> new SegregationRules.Placed(
                            r.batchKey(), r.segregationCategory(), r.slotNo()))
                    .toList();
            int required = SegregationRules.requiredDividerCount(placement);
            if (pallet.dividerCount() < required) {
                throw ApiException.unprocessable("SEGREGATION_INVALID",
                        "装运前复核发现隔板不足：实际 " + pallet.dividerCount() + "，要求 " + required
                                + "，差额 " + (pallet.dividerCount() - required));
            }

            String now = now();
            List<ShipPalletResponse.SnapshotBatch> snapshot = new ArrayList<>(active.size());
            for (PalletRepository.LoadingRow row : active) {
                palletRepo.insertShipment(new PalletRepository.ShipmentRow(0L, palletKey,
                        row.batchKey(), row.segregationCategory(), row.slotNo(),
                        pallet.dividerVersion(), row.seq(), now));
                snapshot.add(new ShipPalletResponse.SnapshotBatch(row.batchKey(),
                        row.segregationCategory(), row.slotNo(), pallet.dividerVersion()));
            }
            palletRepo.updateStatus(palletKey, PalletStatus.SHIPPED.name());
            palletRepo.insertEvent(new PalletRepository.EventRow(0L, palletKey,
                    PalletEventType.SHIPPED.name(),
                    "装运放行 " + active.size() + " 批；实际隔板 " + pallet.dividerCount()
                            + "，要求 " + required + "，固化隔板版本 " + pallet.dividerVersion(),
                    now));
            ShipPalletResponse body = new ShipPalletResponse(palletKey, PalletStatus.SHIPPED,
                    pallet.dividerCount(), pallet.dividerVersion(), List.copyOf(snapshot),
                    Instant.parse(now));
            return new StoredResponse(201, toJson(body));
        });
    }

    /**
     * 已装运托盘事后发现类别错误：仅 SHIPPED 托盘可进入隔离处置 QUARANTINED；
     * 不删除任何装载记录或装运快照。
     */
    public StoredResponse quarantine(String palletKey, String reason, String commandKey) {
        String fingerprint = fingerprint("quarantine", palletKey, reason);
        return executeIdempotent(CMD_QUARANTINE, commandKey, fingerprint, () -> {
            PalletRepository.PalletRow pallet = palletRepo.findPalletForUpdate(palletKey)
                    .orElseThrow(() -> ApiException.notFound("托盘不存在: " + palletKey));
            if (!PalletStatus.SHIPPED.name().equals(pallet.status())) {
                throw ApiException.conflict("托盘状态 " + pallet.status()
                        + " 不允许隔离处置，仅已装运 SHIPPED 托盘可进入隔离处置；"
                        + "未装运问题应通过解除装载处理，不得删除装载记录");
            }
            String now = now();
            palletRepo.updateStatus(palletKey, PalletStatus.QUARANTINED.name());
            palletRepo.insertEvent(new PalletRepository.EventRow(0L, palletKey,
                    PalletEventType.QUARANTINED.name(),
                    "已装运托盘发现类别错误，进入隔离处置；原因：" + reason
                            + "；装载记录与装运快照全部保留", now));
            QuarantinePalletResponse body = new QuarantinePalletResponse(palletKey,
                    PalletStatus.QUARANTINED, reason, Instant.parse(now));
            return new StoredResponse(200, toJson(body));
        });
    }

    // ========== 召回联动（由 BatchService 召回事务内调用，加入同一事务） ==========

    /**
     * 血缘召回联动：hitKeys 为被召回批次及其全部后代；其中任一批次当前位于未装运（OPEN）托盘时，
     * 该托盘所有 ACTIVE 批次标记待复核并写 REVIEW_FLAGGED 事件。仅做持久化操作，加入调用方事务。
     *
     * @return 实际新写入的待复核标记数量（业务诊断用）
     */
    public int applyRecallReview(String recalledKey, List<String> hitKeys) {
        List<PalletRepository.LoadingRow> hitLoadings =
                palletRepo.findActiveLoadingsByBatches(hitKeys);
        if (hitLoadings.isEmpty()) {
            return 0;
        }
        List<String> palletKeys = hitLoadings.stream()
                .map(PalletRepository.LoadingRow::palletKey)
                .distinct().sorted().toList();
        palletRepo.lockPalletsForUpdate(palletKeys);
        String now = now();
        int flagged = 0;
        for (String palletKey : palletKeys) {
            PalletRepository.PalletRow pallet = palletRepo.findPallet(palletKey)
                    .orElseThrow(() -> ApiException.notFound("托盘不存在: " + palletKey));
            // 已装运/已隔离托盘冻结，不新增待复核标记（其处置走隔离处置流程）
            if (!PalletStatus.OPEN.name().equals(pallet.status())) {
                continue;
            }
            for (PalletRepository.LoadingRow row : palletRepo.findActiveLoadings(palletKey)) {
                int inserted = palletRepo.insertReviewFlagIfAbsent(palletKey, row.batchKey(),
                        recalledKey, now);
                if (inserted > 0) {
                    flagged++;
                    palletRepo.insertEvent(new PalletRepository.EventRow(0L, palletKey,
                            PalletEventType.REVIEW_FLAGGED.name(),
                            "血缘召回命中批次 " + recalledKey + "，未装运批次 " + row.batchKey()
                                    + "（分隔位 " + row.slotNo() + "，类别 "
                                    + row.segregationCategory() + "）标记待复核", now));
                }
            }
        }
        return flagged;
    }

    // ========== 只读查询 ==========

    /**
     * 托盘列表概要（只读），按创建顺序排列。
     */
    public List<PalletResponse> listPallets() {
        List<PalletResponse> result = new ArrayList<>();
        for (PalletRepository.PalletRow row : palletRepo.findAllPallets()) {
            result.add(toPalletResponse(row, palletRepo.findActiveLoadings(row.palletKey())));
        }
        return result;
    }

    /**
     * 托盘完整诊断视图（只读）：当前装载、完整历史（含已解除行）、装运快照、事件与待复核标记。
     */
    public PalletDetailResponse palletDetail(String palletKey) {
        PalletRepository.PalletRow pallet = palletRepo.findPallet(palletKey)
                .orElseThrow(() -> ApiException.notFound("托盘不存在: " + palletKey));
        List<PalletRepository.LoadingRow> active = palletRepo.findActiveLoadings(palletKey);
        PalletResponse summary = toPalletResponse(pallet, active);

        List<LoadingDetail> history = palletRepo.findAllLoadings(palletKey).stream()
                .map(this::toLoadingDetail)
                .sorted(Comparator.comparing(LoadingDetail::loadedAt)
                        .thenComparing(d -> d.seq()))
                .toList();

        List<PalletRepository.ShipmentRow> shipmentRows = palletRepo.findShipment(palletKey);
        ShipPalletResponse shipment = null;
        if (!shipmentRows.isEmpty()) {
            List<ShipPalletResponse.SnapshotBatch> snapshot = shipmentRows.stream()
                    .map(s -> new ShipPalletResponse.SnapshotBatch(s.batchKey(),
                            s.segregationCategory(), s.slotNo(), s.dividerVersion()))
                    .toList();
            shipment = new ShipPalletResponse(palletKey, PalletStatus.valueOf(pallet.status()),
                    pallet.dividerCount(), shipmentRows.get(0).dividerVersion(), snapshot,
                    Instant.parse(shipmentRows.get(0).shippedAt()));
        }

        List<PalletEventResponse> events = palletRepo.findEvents(palletKey).stream()
                .map(e -> new PalletEventResponse(PalletEventType.valueOf(e.eventType()),
                        e.detail(), Instant.parse(e.createdAt())))
                .toList();
        List<ReviewFlagResponse> flags = palletRepo.findReviewFlags(palletKey).stream()
                .map(f -> new ReviewFlagResponse(f.palletKey(), f.batchKey(),
                        f.sourceRecalledKey(), Instant.parse(f.createdAt())))
                .toList();
        return new PalletDetailResponse(summary, history, shipment, events, flags);
    }

    // ========== 内部辅助 ==========

    private PalletRepository.PalletRow lockOpenPallet(String palletKey) {
        PalletRepository.PalletRow pallet = lockPalletForUpdate(palletKey);
        if (!PalletStatus.OPEN.name().equals(pallet.status())) {
            throw ApiException.conflict("托盘状态 " + pallet.status()
                    + "，仅未装运 OPEN 托盘允许该操作");
        }
        return pallet;
    }

    private PalletRepository.PalletRow lockPalletForUpdate(String palletKey) {
        return palletRepo.findPalletForUpdate(palletKey)
                .orElseThrow(() -> ApiException.notFound("托盘不存在: " + palletKey));
    }

    private Integer collidingSlot(List<SegregationRules.Placed> placement) {
        Map<Integer, String> used = new LinkedHashMap<>();
        for (SegregationRules.Placed p : placement) {
            if (used.containsKey(p.slotNo())) {
                return p.slotNo();
            }
            used.put(p.slotNo(), p.batchKey());
        }
        return null;
    }

    private void clearReviewFlag(String batchKey) {
        // PalletRepository 未提供删除入口时通过 JdbcTemplate 不可见；这里借助标志幂等特性：
        // 解除后批次不再 ACTIVE，标志是否清理由仓储方法负责。
        palletRepo.deleteReviewFlag(batchKey);
    }

    private Optional<String> recalledAncestor(String batchKey) {
        Map<String, String> parentOf = new LinkedHashMap<>();
        for (BatchRepository.LineageRow row : batchRepo.findAllLineage()) {
            parentOf.put(row.childKey(), row.parentKey());
        }
        Set<String> recalled = new java.util.HashSet<>(batchRepo.findRecalledKeys());
        String current = batchKey;
        while (parentOf.containsKey(current)) {
            current = parentOf.get(current);
            if (recalled.contains(current)) {
                return Optional.of(current);
            }
        }
        return Optional.empty();
    }

    private PalletResponse toPalletResponse(PalletRepository.PalletRow row,
                                            List<PalletRepository.LoadingRow> active) {
        return new PalletResponse(row.palletKey(), PalletStatus.valueOf(row.status()),
                row.dividerCount(), row.dividerVersion(),
                active.stream().map(this::toLoadingDetail).toList(),
                Instant.parse(row.createdAt()));
    }

    private LoadingDetail toLoadingDetail(PalletRepository.LoadingRow row) {
        return new LoadingDetail(row.palletKey(), row.batchKey(), row.segregationCategory(),
                row.slotNo(), row.dividerVersion(), row.seq(),
                Instant.parse(row.loadedAt()),
                row.unloadedAt() == null ? null : Instant.parse(row.unloadedAt()));
    }

    /**
     * 幂等执行：同键同参返回首次快照，同键异参 409；命令日志唯一键冲突时重试读快照；
     * 业务唯一约束（批次/分隔位）逃逸为 DuplicateKeyException 时转 422，不重试、不占键。
     */
    private StoredResponse executeIdempotent(String type, String commandKey, String fingerprint,
                                             Supplier<StoredResponse> action) {
        for (int attempt = 0; attempt < IDEMPOTENCY_MAX_ATTEMPTS; attempt++) {
            try {
                return tx.execute(status -> {
                    var logged = palletRepo.findCommand(type, commandKey);
                    if (logged.isPresent()) {
                        return replayOrConflict(logged.get(), fingerprint);
                    }
                    StoredResponse response = action.get();
                    palletRepo.insertCommand(type, commandKey, fingerprint,
                            response.status(), response.body(), now());
                    return response;
                });
            } catch (DuplicateKeyException e) {
                if (looksLikeCommandLogConflict(e)) {
                    continue;
                }
                throw ApiException.unprocessable("BATCH_OCCUPIED_OTHER_PALLET",
                        "并发装载冲突：批次已被另一事务抢先装载到其他托盘（唯一约束裁决）");
            }
        }
        throw ApiException.conflict("命令并发冲突，请重试: " + commandKey);
    }

    private StoredResponse replayOrConflict(PalletRepository.CommandView row, String fingerprint) {
        if (!row.fingerprint().equals(fingerprint)) {
            throw ApiException.conflict("commandKey 已以不同参数使用");
        }
        return new StoredResponse(row.responseStatus(), row.responseBody());
    }

    private boolean looksLikeCommandLogConflict(DuplicateKeyException e) {
        String message = e.getMessage() == null ? "" : e.getMessage();
        return message.contains("COMMAND_LOG") || message.contains("command_log")
                || message.contains("PRIMARY_KEY") || message.contains("PRIMARY KEY");
    }

    private String now() {
        return Instant.now(clock).toString();
    }

    private String toJson(Object body) {
        try {
            return objectMapper.writeValueAsString(body);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("响应序列化失败", e);
        }
    }

    private String fingerprint(String... parts) {
        String canonical = String.join(SEP, parts);
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(canonical.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(hash.length * 2);
            for (byte b : hash) {
                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
                hex.append(Character.forDigit(b & 0xF, 16));
            }
            return hex.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 不可用", e);
        }
    }
}

