    private void releaseBatch(String batchKey) throws Exception {
        submitPass(batchKey);
        mockMvc.perform(post("/api/batches/" + batchKey + "/approvals")
                        .header("X-Actor-Id", "qa-" + uniq()).header("X-Approval-Role", "QUALITY")
